fn program(gates: &[(usize, usize, f64)]) -> OperatorProgram {
    OperatorProgram::new(
        DIMENSION,
        gates
            .iter()
            .map(|&(left, right, angle)| PlaneRotation { left, right, angle })
            .collect(),
    )
    .expect("generated protected fixture must be valid")
}

fn dense_apply(
    matrix: &[[f64; DIMENSION]; DIMENSION],
    state: &[f64; DIMENSION],
) -> [f64; DIMENSION] {
    let mut output = [0.0; DIMENSION];
    for (row_index, output_value) in output.iter_mut().enumerate() {
        *output_value = matrix[row_index]
            .iter()
            .zip(state.iter())
            .map(|(coefficient, value)| coefficient * value)
            .sum();
    }
    output
}

fn norm_squared(state: &[f64; DIMENSION]) -> f64 {
    state.iter().map(|value| value * value).sum()
}

fn max_abs_difference(left: &[f64; DIMENSION], right: &[f64; DIMENSION]) -> f64 {
    left.iter()
        .zip(right.iter())
        .map(|(a, b)| (a - b).abs())
        .fold(0.0, f64::max)
}

fn apply_program(
    program: &OperatorProgram,
    input: [f64; DIMENSION],
) -> [f64; DIMENSION] {
    let mut output = input;
    program.apply(&mut output).expect("dimension is fixed");
    output
}

#[test]
fn sparse_executor_replays_protected_bundle_holonomies() {
    let a = program(&GATES_A);
    let b = program(&GATES_B);
    for coordinate in 0..DIMENSION {
        let mut basis = [0.0; DIMENSION];
        basis[coordinate] = 1.0;

        let actual_a = apply_program(&a, basis);
        let expected_a = dense_apply(&TARGET_A, &basis);
        assert!(max_abs_difference(&actual_a, &expected_a) < 2.0e-13);
        assert!((norm_squared(&actual_a) - 1.0).abs() < 2.0e-13);

        let actual_b = apply_program(&b, basis);
        let expected_b = dense_apply(&TARGET_B, &basis);
        assert!(max_abs_difference(&actual_b, &expected_b) < 2.0e-13);
        assert!((norm_squared(&actual_b) - 1.0).abs() < 2.0e-13);
    }
}

#[test]
fn protected_bundle_gates_are_nonabelian_in_rust() {
    let a = program(&GATES_A);
    let b = program(&GATES_B);
    let mut initial = [0.0; DIMENSION];
    initial[0] = 1.0;

    let state_ab = apply_program(&b, apply_program(&a, initial));
    let state_ba = apply_program(&a, apply_program(&b, initial));
    let distance = state_ab
        .iter()
        .zip(state_ba.iter())
        .map(|(left, right)| (left - right).powi(2))
        .sum::<f64>()
        .sqrt();

    assert!(distance > 1.19, "AB/BA state distance={distance}");
    assert!((norm_squared(&state_ab) - 1.0).abs() < 4.0e-13);
    assert!((norm_squared(&state_ba) - 1.0).abs() < 4.0e-13);
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum PumpMode {
    Plus,
    Minus,
    Link,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
struct PumpState {
    cell: i32,
    mode: PumpMode,
}

fn c3(state: PumpState) -> PumpState {
    match state.mode {
        PumpMode::Plus => PumpState {
            mode: PumpMode::Link,
            ..state
        },
        PumpMode::Link => PumpState {
            mode: PumpMode::Minus,
            ..state
        },
        PumpMode::Minus => PumpState {
            mode: PumpMode::Plus,
            ..state
        },
    }
}

fn c3_prime(state: PumpState) -> PumpState {
    match state.mode {
        PumpMode::Plus => PumpState {
            mode: PumpMode::Minus,
            ..state
        },
        PumpMode::Minus => PumpState {
            cell: state.cell - 1,
            mode: PumpMode::Link,
        },
        PumpMode::Link => PumpState {
            cell: state.cell + 1,
            mode: PumpMode::Plus,
        },
    }
}

#[test]
fn exact_z3_acoustic_pump_algebra_is_order_sensitive() {
    let modes = [PumpMode::Plus, PumpMode::Minus, PumpMode::Link];
    for mode in modes {
        let state = PumpState { cell: 0, mode };
        assert_eq!(c3(c3(c3(state))), state);
        assert_eq!(c3_prime(c3_prime(c3_prime(state))), state);
    }

    let initial = PumpState {
        cell: 0,
        mode: PumpMode::Plus,
    };
    assert_ne!(c3(c3_prime(initial)), c3_prime(c3(initial)));

    let path_one = c3(c3_prime(c3(c3(initial))));
    let path_two = c3(c3(c3(c3_prime(initial))));
    assert_eq!(path_one.mode, path_two.mode);
    assert_eq!(path_one.cell, -1);
    assert_eq!(path_two.cell, 0);
}
